import { tool } from "@opencode-ai/plugin"

export default tool({
  description:
    "Get the current opencode session's metadata: session ID, working directory, and worktree root. Call this at the start of a session to learn your own identity, or anytime you need to reference your session ID for logging, status updates, or coordination with other agents.",
  args: {},
  async execute(_args, context) {
    const { agent, sessionID, messageID, directory, worktree } = context

    const lines = [
      `Session ID: ${sessionID}`,
      // `Agent: ${agent || "default"}`,
      // `Current Message ID: ${messageID}`,
      `Working Directory: ${directory}`,
      `Worktree Root: ${worktree || directory}`,
    ]

    return lines.join("\n")
  },
})
